import React, { useState } from "react";
import "../css/SignIn.css";
import googleIcon from "../assets/google-brands-solid.svg";
import twitterIcon from "../assets/x-twitter-brands-solid.svg";
import { Link } from "react-router-dom";
import { useSignUp } from '@clerk/clerk-react';

const VerificationInput = ({ onVerify, error }) => {
  const [code, setCode] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onVerify(code);
  };

  return (
    <form onSubmit={handleSubmit} className="verification-form">
      <label htmlFor="verificationCode">Enter Verification Code</label>
      <input
        type="text"
        id="verificationCode"
        name="verificationCode"
        value={code}
        onChange={(e) => setCode(e.target.value)}
        placeholder="123456"
        required
      />
      <button type="submit" className="submit">Verify</button>
      {error && <p className="error">{error.message || error.toString()}</p>}
    </form>
  );
};

const SignUp = () => {
  const { signUp, isLoaded } = useSignUp();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [step, setStep] = useState('signUp');
  const [error, setError] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  if (!isLoaded) return null;

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    try {
      // Create user with email and password. Clerk doesn't require username by default but you can add it as metadata if needed.
      await signUp.create({ emailAddress: email, password });

      // Prepare email verification using code strategy
      await signUp.prepareEmailAddressVerification({ strategy: "email_code" });

      setStep('verify');
    } catch (err) {
      setError(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerify = async (code) => {
    setError(null);
    setIsLoading(true);

    try {
      await signUp.attemptEmailAddressVerification({ code });

      // Log user in by setting the session
      await setSession(signUp.createdSessionId);

      // After success, you can redirect or reset form, up to you.
      // For example, you may do:
      // navigate('/dashboard') or reset form and state here
    } catch (err) {
      setError(err);
    } finally {
      setIsLoading(false);
    }
  };

  // Optionally, add handlers for Twitter & Google sign-in if you want to implement social logins via Clerk's OAuth.

  if (step === 'verify') {
    return <VerificationInput onVerify={handleVerify} error={error} />;
  }

  return (
    <div className="container">
      <h1 className="header">Register</h1>
      <p className="subtext">
        Already have an account? <Link to="/login">Log In</Link>
      </p>

      <form onSubmit={handleSignUp}>
        <label htmlFor="username">Username</label>
        <input
          type="text"
          id="username"
          name="username"
          placeholder="john"
          value={username}
          onChange={e => setUsername(e.target.value)}
        />

        <label htmlFor="email">Email</label>
        <input
          type="email"
          id="email"
          name="email"
          placeholder="m@example.com"
          value={email}
          onChange={e => setEmail(e.target.value)}
          required
        />

        <label htmlFor="password">Password</label>
        <input
          type="password"
          id="password"
          name="password"
          value={password}
          onChange={e => setPassword(e.target.value)}
          required
          minLength={8}
        />

        <button type="submit" className="submit" disabled={isLoading}>
          {isLoading ? "Signing up..." : "Sign Up"}
        </button>

        {error && <p className="error">{error.message || error.toString()}</p>}
      </form>

      <div className="divider">
        <span>OR</span>
      </div>

      <div className="button-group">
        <button type="button" className="button" /* add your social login logic here if any */>
          <img src={twitterIcon} alt="Twitter Icon" width={20} height={20} /> Twitter
        </button>
        <button type="button" className="button" /* add your social login logic here if any */>
          <img src={googleIcon} alt="Google Icon" width={20} height={20} /> Google
        </button>
      </div>
    </div>
  );
};

export default SignUp;
